import{_ as t,o,c as r,ag as a}from"./chunks/framework.HG0H2VLS.js";const h=JSON.parse('{"title":"PromptModifier (CC) — figma notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/cc/patterns/PromptModifier/PromptModifier.figma-notes.md","filePath":"public/demos/src/cc/patterns/PromptModifier/PromptModifier.figma-notes.md"}'),i={name:"public/demos/src/cc/patterns/PromptModifier/PromptModifier.figma-notes.md"};function n(s,e,d,p,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="promptmodifier-cc-—-figma-notes" tabindex="-1">PromptModifier (CC) — figma notes <a class="header-anchor" href="#promptmodifier-cc-—-figma-notes" aria-label="Permalink to &quot;PromptModifier (CC) — figma notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern · <strong>Status:</strong> CODE-FIRST (designer, 2026-09-29). <strong>No Figma node.</strong> Flagged for Figma; check with Mark before any push. Composes Button and Textarea.</p><p>This is the AI prompt on the record sections that the live Control Centre generates: <strong>Social</strong> (ShareLineGenerationPrompt), <strong>Article Questions</strong> (QuestionGenerationPrompt) and <strong>Summary</strong> (SummaryGenerationPrompt). The prompt text is live&#39;s own (affino.com 626312, read 2026-09-29). Live shows the full prompt textarea, a Generate button and Copy / Expand icons above the fields.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>A tinted panel (<code>--ai-surface-extra-minimal</code>, designer amend 2026-09-29, was brand-soft-extra; <code>--ai-border-secondary</code>, <code>--ai-radius-md</code>, <code>--ai-spacing-4</code> padding) at the top of the section body. It reads as tooling that writes the fields below it, not as an article field.</p><ul><li><strong>At rest, one row:</strong> a sparkles icon (<code>--ai-icon-brand</code>), then the title plus what it fills (&quot;Fills Shareline 1–3&quot;), a one-line ellipsised <strong>preview</strong> of the prompt, <strong>Edit prompt</strong> (tertiary sm, chevron) and <strong>Generate</strong> (secondary sm, sparkles). The page&#39;s Save stays the only primary.</li><li><strong>Edit prompt</strong> opens the prompt textarea (on <code>--ai-surface-primary</code>), a hint and <strong>Copy prompt</strong>. The preview hides while it is open and follows edits.</li><li><strong>Generate:</strong> a busy state (label &quot;Generating…&quot;, the sparkles icon spins, and it respects reduced motion). It then fills the fields that follow the panel, in order, flashes them with a <code>--ai-surface-brand-soft</code> ring, and shows &quot;Generated n fields just now.&quot; with <strong>Undo</strong>, because Generate overwrites.</li><li><strong>Narrow</strong> (<code>@container prompt-modifier (max-width: 479px)</code>): the actions drop to their own row, left-aligned with the title and preview, indented past the icon (designer, 2026-09-29).</li></ul><p>Live&#39;s per-field &quot;Expand&quot; arrows are not carried over: our textareas resize natively.</p><h2 id="handover" tabindex="-1">Handover <a class="header-anchor" href="#handover" aria-label="Permalink to &quot;Handover&quot;">​</a></h2><ul><li><code>record-prompt-generate</code>: canned outputs; needs the AI endpoint.</li><li><code>record-prompt-save</code>: the edited prompt is not saved.</li></ul><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>PromptModifier.css and PromptModifier.js. <code>PromptModifier.html</code> is <strong>generated</strong> by <code>src/cc/templates/RecordScreen/_generate.py</code>.</p>',11)])])}const f=t(i,[["render",n]]);export{h as __pageData,f as default};
